  return `${g}, ${this.name}`;
}
const user = { name: 'Ada' };
greet.call(user, 'Hi');
const hi = greet.bind(user, 'Hi');
hi();

const obj = {
  n: 1,
  regular() { return this.n; },
  arrow: () => this.n, // outer this, not obj
};
obj.regular(); // 1
obj.arrow(); // undefined (or global) in modules/strict

